"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('lower', 10), ('upper', 46), ('river', 31), ('lower', 3), ('lower', 33)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)


def feed_harvests():
    """Endless feed of harvests: repeats the stored rows for ever."""
    while True:
        for field, kilos in ROWS:
            yield Harvest(field, kilos)

