"""Halves of a window over the harvests feed."""
import itertools


def split_window(feed, size):
    """Read the next `size` harvests from the feed and return their kilos as (first half, second half).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = [x.kilos for x in itertools.islice(feed, size)]
    half = size // 2
    return window[:half], window[size:]


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names


def group_by_field(harvests):
    """Return a dict from field to the list of harvests with that field."""
    groups = {}
    for x in harvests:
        groups.setdefault(x.field, []).append(x)
    return groups
